        settings.SEARCH_AUTHOR = true        // 搜索：默认搜索作者名称
    }
    settings.IS_LEGADO = !isSourceRead()
    settings.IS_SOURCE_READ = isSourceRead()
    settings.IS_BACKUP_SOURCE = isBackupSource()
    u.settings = settings
    putInCache("pixivSettings", settings)  // 设置写入缓存

    u.debugFunc = (func) => {
